window.VN_LEARNING=window.VN_LEARNING||{};
window.VN_LEARNING["lesson-9"]={
  version:2,title:"Vegetarian Diets — Pregnancy & Lactation",chapter:9,duration:"115–140 minutes",
  outcomes:["Explain why current adult vegetarian guidance cannot be applied automatically to pregnancy and lactation.","Build a preconception and prenatal nutrient checklist without inventing universal supplement doses.","Recognize the iodine unit error in the supplied quiz and distinguish micrograms from milligrams.","Plan reliable B12, iron, iodine, vitamin D, calcium, protein, energy, choline and omega-3 support.","Audit a prenatal product for nutrients that are missing, low, duplicated or in an unsuitable form.","Use cautious evidence language and identify symptoms or situations requiring prenatal care."],
  modules:[
    {id:"scope-preconception",title:"Set the evidence boundary before conception",summary:"Use current life-stage guidance, acknowledge uncertainty and improve status before pregnancy begins.",moments:[
      {id:"l9-m1",title:"Adult adequacy claims do not automatically cover pregnancy",highYield:"The Academy's 2025 vegetarian position addresses adults and explicitly does not establish pregnancy or lactation guidance.",teaching:["Older position statements often said well-planned vegetarian diets were appropriate for all life stages. Current evidence needs more careful wording. The 2025 Academy position focuses on adults; pregnancy and lactation require separate evidence, obstetric guidance and individualized monitoring.","Recent systematic reviews suggest that vegetarian or vegan pregnancies can be compatible with healthy outcomes, but the evidence is limited, heterogeneous and confounded by diet quality, supplement use, socioeconomic factors and how diets are defined. Some analyses report lower birth weight or small-for-gestational-age signals. Teach possibility and planning, not automatic equivalence or alarm."],keyPoints:["Current adult position papers have a defined scope.","Pregnancy evidence is limited and heterogeneous.","Pattern quality and supplementation vary.","Use cautious, non-causal language."],visual:{title:"Evidence boundary",kind:"layers",items:[{label:"Adult evidence",detail:"Useful foundation but not a pregnancy protocol"},{label:"Pregnancy studies",detail:"Mostly observational and heterogeneous"},{label:"Clinical guidance",detail:"Prenatal care, local policy and biomarkers"},{label:"Individual plan",detail:"Diet pattern, health history, access and preferences"}]},mnemonic:{title:"SCOPE",cue:"Scope · Context · Outcomes · Plan · Escalate",explanation:"Check what the evidence actually covers before counselling."},goodToKnow:"A reassuring population association cannot guarantee an individual outcome, and a risk signal does not prove the diet caused it.",practiceConnection:"Document dietary pattern precisely—vegan, lacto-ovo, occasional animal foods, supplements and fortification—rather than using vegetarian as one exposure.",activity:{prompt:"How should the 2025 adult vegetarian position be used in pregnancy?",options:[{text:"As adult background, supplemented with pregnancy-specific evidence and care",correct:true,feedback:"Correct. Its scope does not establish a prenatal protocol."},{text:"As proof that every vegetarian pregnancy has identical risk",correct:false,feedback:"The evidence does not support that certainty."},{text:"As a reason to abandon all plant foods",correct:false,feedback:"Plant foods remain valuable; the issue is life-stage planning and monitoring."}]}} ,
      {id:"l9-m2",title:"Preconception is the best time to close predictable gaps",highYield:"Verify folic acid, B12, iron status, iodine, vitamin D, calcium, energy and medication safety before pregnancy when possible.",teaching:["Neural-tube development begins early, often before pregnancy is recognized. Follow jurisdiction-specific folic-acid guidance before conception and during early pregnancy. A vegan plan also requires a verified B12 source; folic acid cannot protect against B12 neurologic deficiency.","Preconception review includes dietary adequacy, weight trajectory, menstrual history, prior pregnancy outcomes, medicines, alcohol and smoking, food security and relevant biomarkers. Iron and vitamin D supplementation should reflect local prenatal policy and individual results. Improving status beforehand creates more reserve than waiting for symptoms."],keyPoints:["Folic acid planning begins before conception.","Verify B12, not just folate.","Assess iron and vitamin D context.","Review medicines and food access."],visual:{title:"Preconception checklist",kind:"map",items:[{label:"Foundation",detail:"Energy, protein, varied foods and food security"},{label:"Reliable nutrients",detail:"Folic acid, B12 and iodine plan"},{label:"Assess",detail:"Iron, vitamin D and other risks"},{label:"Safety",detail:"Medicines, alcohol, smoking and food hazards"},{label:"Coordinate",detail:"Prenatal clinician and qualified nutrition care"}]},mnemonic:{title:"FAB-I",cue:"Folate · B12 · Iron · Iodine",explanation:"A short cue for nutrients that deserve explicit preconception review; it is not the whole plan."},goodToKnow:"The best plan is the one actually started before conception and reviewed as pregnancy progresses.",practiceConnection:"Do not tell a client to stop prescribed medicines or begin high-dose supplements without the prenatal care team.",activity:{prompt:"Why begin folic-acid planning before pregnancy is confirmed?",options:[{text:"Neural-tube development begins very early",correct:true,feedback:"Correct. Early development may precede pregnancy recognition."},{text:"Folate replaces B12 during pregnancy",correct:false,feedback:"Folate and B12 are not interchangeable."},{text:"It guarantees no pregnancy complications",correct:false,feedback:"It reduces a specific risk but cannot guarantee outcomes."}]}}
    ]},
    {id:"nutrient-plan",title:"Build a pregnancy nutrient safety net",summary:"Cover the predictable priorities without turning one historic serving table into a universal prescription.",moments:[
      {id:"l9-m3",title:"Energy and protein rise through pregnancy, but the pattern stays food-based",highYield:"Use adequate meals and protein anchors; a fixed number of 'bean alternate' servings is a planning aid, not a universal dose.",teaching:["Energy needs do not rise equally in every trimester, and individual recommendations depend on prepregnancy status, activity, fetal growth and clinical context. Protein needs increase with tissue growth. Regular legumes, tofu, tempeh, soy foods, seitan, nuts/seeds, and eggs or dairy when used can provide adequate protein within a varied pattern.","An older question asks for a specific number of bean-and-alternate servings. Historic food-guide servings can help visualize intake but are not current universal clinical prescriptions. Assess grams, food portions, appetite, nausea, cultural staples and actual growth rather than scoring pregnancy from one serving count."],keyPoints:["Energy needs change across pregnancy.","Protein-rich foods should recur across the day.","Serving systems are planning tools, not physiology.","Growth and intake need ongoing review."],visual:{title:"Pregnancy meal rhythm",kind:"sequence",items:[{label:"Morning",detail:"Tolerable food and fluid if nausea is present"},{label:"Meals",detail:"Protein anchor plus energy base and produce"},{label:"Snacks",detail:"Energy- and nutrient-dense support"},{label:"Daily safeguards",detail:"Prenatal supplement, B12 and iodine plan"},{label:"Monitor",detail:"Weight trajectory, symptoms and clinical measures"}]},mnemonic:{title:"Anchor every eating window",cue:"Protein + energy + tolerated food",explanation:"Frequent smaller eating may help when appetite or nausea limits meals."},goodToKnow:"Eating soon after waking may help some people with nausea, but it is a symptom strategy—not a universal cure.",practiceConnection:"Persistent vomiting, dehydration, inability to keep food down or significant weight loss needs prompt prenatal assessment.",activity:{prompt:"How should an old 'bean servings' target be used?",options:[{text:"As one planning reference alongside current needs, portions and clinical monitoring",correct:true,feedback:"Correct. It should not become a rigid universal prescription."},{text:"As the only measure of pregnancy adequacy",correct:false,feedback:"Pregnancy nutrition is broader and individualized."},{text:"As proof that all legumes have identical composition",correct:false,feedback:"Foods and portions vary."}]}} ,
      {id:"l9-m4",title:"Iron, B12 and iodine need deliberate verification",highYield:"Pregnancy increases the cost of a gap; reliable sources, prenatal policy and assessment should be explicit.",teaching:["Iron needs rise substantially as blood volume expands and fetal tissues develop. Plant iron is nonheme and benefits from vitamin C pairing, but many pregnant people require supplementation under prenatal guidance. The statement that it is always impossible to meet needs with food is too absolute; the safer point is that food intake and iron status require close review.","B12 must come from a dependable fortified food or supplement, especially in vegan pregnancy. Iodine supports maternal thyroid hormone and fetal neurodevelopment. The supplied quiz says 150 mg iodine—almost certainly a dangerous unit error. Prenatal recommendations are expressed in micrograms; 150 mg equals 150,000 micrograms. Dose and form must be checked with current local guidance."],keyPoints:["Iron demand rises during pregnancy.","Vitamin C supports nonheme iron absorption.","B12 requires a reliable source.","Iodine guidance uses micrograms, not the quiz's milligrams."],visual:{title:"Three high-consequence checks",kind:"comparison",items:[{label:"Iron",detail:"Food sources, vitamin C, ferritin/hemoglobin and prenatal plan"},{label:"B12",detail:"Verified source, dose, adherence and biomarkers if indicated"},{label:"Iodine",detail:"Microgram dose, potassium iodide form and thyroid context"}]},mnemonic:{title:"IBI",cue:"Iron · B12 · Iodine",explanation:"Three nutrients where a vague 'healthy diet' answer is not enough."},goodToKnow:"One milligram equals 1,000 micrograms; unit literacy is a patient-safety skill.",practiceConnection:"Do not convert the corrected unit into an individualized dose. Confirm current Health Canada or local prenatal guidance and thyroid history.",activity:{prompt:"What is wrong with '150 mg iodine' in the supplied question?",options:[{text:"It likely confuses milligrams with micrograms, a thousand-fold difference",correct:true,feedback:"Correct. This is a high-risk source error."},{text:"Milligrams and micrograms are identical",correct:false,feedback:"A milligram is 1,000 micrograms."},{text:"Iodine has no role in pregnancy",correct:false,feedback:"Iodine supports thyroid hormone and fetal development."}]}}
    ]},
    {id:"fats-safety",title:"Support development and food safety",summary:"Plan omega-3s, calcium/D and safe food choices while managing symptoms without overpromising.",moments:[
      {id:"l9-m5",title:"DHA planning is a direct-source decision",highYield:"Maternal DHA status contributes to fetal supply; algal DHA is the measured vegetarian direct source.",teaching:["DHA accumulates in neural and retinal tissues, especially later in pregnancy. The body can make some DHA from ALA, but conversion is limited and variable. Regular ALA foods remain important, while a measured algal DHA supplement is the direct vegetarian option considered in pregnancy guidance.","Cord-blood DHA comparisons between dietary groups depend on intake, supplements, genetics and study design; an old true-or-false statement is not a universal biological rule. Review the prenatal product, total dose, purity and other supplements with qualified care rather than adding several overlapping products."],keyPoints:["ALA is essential and food-based.","Conversion to DHA is limited and variable.","Algal DHA is a direct vegetarian source.","Supplement decisions are individualized."],visual:{title:"Maternal omega-3 pathway",kind:"flow",items:[{label:"ALA foods",detail:"Flax, chia, hemp, walnuts and selected oils"},{label:"Conversion",detail:"Limited and variable EPA/DHA production"},{label:"Direct source",detail:"Measured algal DHA"},{label:"Maternal circulation",detail:"Supplies placental transfer"},{label:"Fetal tissue",detail:"DHA accumulates in brain and retina"}]},mnemonic:{title:"A to D",cue:"ALA food · Algal DHA",explanation:"Keep the essential precursor and direct-source option distinct."},goodToKnow:"Omega-3 does not prevent every preterm birth or pregnancy complication; outcome evidence and individual context matter.",practiceConnection:"Review anticoagulants, bleeding disorders and all prenatal supplements before adding concentrated omega-3.",activity:{prompt:"What is the direct vegetarian source of DHA?",options:[{text:"Algal DHA",correct:true,feedback:"Correct. It bypasses variable ALA conversion."},{text:"Table sugar",correct:false,feedback:"Sugar is not an omega-3 source."},{text:"Any sea vegetable in an unmeasured amount",correct:false,feedback:"Sea vegetables are not a predictable DHA dose."}]}} ,
      {id:"l9-m6",title:"Food safety and nausea strategies must remain practical",highYield:"Use pasteurized foods, safe handling and tolerable small meals; symptom tricks do not replace evaluation of severe nausea.",teaching:["Pregnancy food-safety guidance includes avoiding unpasteurized dairy or juice, raw sprouts when advised, undercooked eggs and other high-risk foods, and following local rules for refrigerated ready-to-eat foods. Vegetarian does not mean foodborne risk disappears; sprouts, cut produce and soft cheeses can carry hazards.","For nausea, small frequent meals, food before rising, separating some fluid from meals or choosing colder low-odour foods may help individuals. Large amounts of fluid with a meal can worsen fullness for some but help others. Avoid presenting one tactic as guaranteed. Hyperemesis signs require clinical care."],keyPoints:["Pasteurization and safe handling matter.","Vegetarian foods can carry foodborne pathogens.","Nausea strategies are individualized.","Severe symptoms require escalation."],visual:{title:"Pregnancy safety screen",kind:"map",items:[{label:"Pasteurized",detail:"Milk, cheese and juice when used"},{label:"Cooked",detail:"Eggs and high-risk refrigerated foods per guidance"},{label:"Clean",detail:"Produce, surfaces and hands"},{label:"Cold",detail:"Maintain safe refrigeration"},{label:"Clinical",detail:"Escalate persistent vomiting or dehydration"}]},mnemonic:{title:"P4 + C",cue:"Pasteurized · Prepared safely · Portions tolerated · Plenty of monitoring + Clinical care",explanation:"A practical safety and symptom cue."},goodToKnow:"'Aged' or 'cultured' does not determine safety by itself; pasteurization, storage and product type matter.",practiceConnection:"Use current local food-safety lists because recalls and jurisdictional recommendations change.",activity:{prompt:"Which dairy product presents a clear pregnancy food-safety concern?",options:[{text:"An unpasteurized product",correct:true,feedback:"Correct. Unpasteurized products can carry harmful pathogens."},{text:"Any cultured yogurt made from pasteurized milk",correct:false,feedback:"Culturing alone does not make a pasteurized product unsafe."},{text:"Every food containing calcium",correct:false,feedback:"Calcium content is unrelated to pathogen risk."}]}}
    ]},
    {id:"lactation",title:"Protect lactation and infant supply",summary:"Support maternal intake, understand what milk composition does and does not mirror, and watch B12/iodine/DHA closely.",moments:[
      {id:"l9-m7",title:"Milk production raises needs, but not every milk nutrient tracks intake",highYield:"Maternal status strongly affects some milk nutrients such as B12 and iodine, while milk calcium is comparatively buffered.",teaching:["Lactation requires energy, protein, fluid access and micronutrient planning. Milk production is generally protected over a range of maternal intakes, sometimes at the expense of maternal stores. Calcium concentration in milk is relatively regulated, so very high calcium intake does not simply raise milk calcium; maternal bone and long-term intake still matter.","B12, iodine, vitamin D and fatty-acid patterns deserve explicit review because maternal intake and status can affect infant supply. A breastfed infant of a B12-deficient vegan parent can develop severe neurologic injury. Qualified postpartum and pediatric care should verify both maternal and infant supplementation plans."],keyPoints:["Lactation increases energy and nutrient demands.","Milk calcium is relatively buffered.","Milk B12 and iodine depend more on maternal status.","Infant supplementation follows pediatric guidance."],visual:{title:"Maternal intake to milk",kind:"comparison",items:[{label:"Relatively buffered",detail:"Milk calcium changes little with short-term intake"},{label:"More responsive",detail:"B12, iodine and fatty-acid profile depend more on maternal status/intake"},{label:"Maternal cost",detail:"Stores can be depleted while milk production continues"},{label:"Infant plan",detail:"Growth and supplement guidance require pediatric follow-up"}]},mnemonic:{title:"BID",cue:"B12 · Iodine · DHA",explanation:"Three nutrients to verify explicitly during vegan lactation; vitamin D planning is also essential."},goodToKnow:"Drinking excessive fluid does not automatically increase milk supply; drink to thirst and address feeding mechanics and clinical causes when supply is low.",practiceConnection:"Coordinate with lactation and pediatric professionals for poor infant transfer, low output, jaundice, lethargy or faltering growth.",activity:{prompt:"Which milk nutrient is comparatively buffered against short-term maternal intake?",options:[{text:"Calcium",correct:true,feedback:"Correct. Maternal intake matters for maternal health, but milk calcium is relatively regulated."},{text:"Vitamin B12 in a deficient vegan parent",correct:false,feedback:"Milk B12 can be low when maternal status is inadequate."},{text:"Iodine in every context",correct:false,feedback:"Milk iodine is influenced by maternal intake and status."}]}} ,
      {id:"l9-m8",title:"Postpartum planning continues after birth",highYield:"The prenatal plan should be reviewed—not automatically stopped—when feeding method, recovery, blood loss and infant needs become known.",teaching:["Postpartum needs depend on lactation, blood loss, recovery, appetite, sleep, food access and medical conditions. Iron supplementation may change after laboratory review. B12 and iodine remain critical when breastfeeding, and a prenatal supplement may not contain the right amount or form for every person.","A realistic plan uses quick protein-rich foods, fortified beverages or cereals, frozen produce, prepared legumes and community support. Counselling should protect adequate intake rather than promoting rapid weight loss. Infant feeding, growth and supplementation belong in pediatric follow-up."],keyPoints:["Reassess after delivery.","Blood loss and feeding method change priorities.","B12 and iodine remain important in lactation.","Protect energy and food access."],visual:{title:"Postpartum reassessment",kind:"sequence",items:[{label:"Recover",detail:"Blood loss, healing and symptoms"},{label:"Feed",detail:"Lactation, formula or mixed feeding"},{label:"Review",detail:"Supplements, medicines and labs"},{label:"Resource",detail:"Food access, sleep and support"},{label:"Refer",detail:"Maternal or infant red flags"}]},mnemonic:{title:"R-F-R-R-R",cue:"Recover · Feed · Review · Resource · Refer",explanation:"A five-part postpartum check."},goodToKnow:"Rapid diet restriction can worsen fatigue and reduce nutrient intake during an already demanding period.",practiceConnection:"Maternal mood changes, severe headache, heavy bleeding, chest pain, shortness of breath, fever or infant feeding/growth concerns require urgent clinical pathways.",activity:{prompt:"What is the safest approach to the prenatal supplement after birth?",options:[{text:"Review it against feeding method, diet, labs and current postpartum guidance",correct:true,feedback:"Correct. Needs may continue or change."},{text:"Stop every supplement automatically",correct:false,feedback:"B12, iodine, iron or vitamin D needs may persist."},{text:"Double every dose without assessment",correct:false,feedback:"Higher doses can be unsafe or unnecessary."}]}}
    ]},
    {id:"choline-monitoring",title:"Close the quiet gaps that a prenatal may miss",summary:"Add choline and a full product audit to the pregnancy plan, then use repeated reassessment instead of assuming one pill covers everything.",moments:[
      {id:"l9-m9",title:"Choline is structural, metabolic and easy to overlook",highYield:"Choline supports cell membranes, acetylcholine synthesis, methyl metabolism and fetal nervous-system development; many prenatal products contain little or none.",teaching:["Choline is needed to form phosphatidylcholine and sphingomyelin in cell membranes, to make the neurotransmitter acetylcholine and to support methyl-group and lipid transport pathways. Needs rise in pregnancy and rise further during lactation. Eggs are concentrated sources, so vegan or egg-free patterns require more deliberate use of soybeans and soy foods, legumes, cruciferous vegetables, whole grains, nuts and seeds.","Food composition varies and endogenous synthesis is not enough to assume adequacy. NIH reviews note that most pregnant people do not reach the adequate intake and that many prenatal products contain no choline or only a small amount. Check the label rather than assuming 'prenatal' means complete. Folic acid, B12 and choline share metabolic neighbourhoods but cannot replace one another."],keyPoints:["Choline supports membranes, neurotransmission and methyl metabolism.","Needs increase in pregnancy and lactation.","Vegan patterns need deliberate food and product review.","Many prenatal supplements contain little or no choline."],visual:{title:"Choline roles and routes",kind:"map",items:[{label:"Structure",detail:"Phosphatidylcholine and sphingomyelin in cell membranes"},{label:"Signalling",detail:"Acetylcholine synthesis"},{label:"Metabolism",detail:"Methyl transfer and lipid transport"},{label:"Plant foods",detail:"Soy, legumes, crucifers, whole grains, nuts and seeds"},{label:"Gap check",detail:"Prenatal label plus total diet"}]},mnemonic:{title:"M-N-M",cue:"Membranes · Nerves · Methyl groups",explanation:"Three major reasons choline belongs in prenatal assessment."},goodToKnow:"There is no single routine blood test that cleanly diagnoses dietary choline inadequacy in everyday care; intake assessment and product review matter.",practiceConnection:"Photograph the full supplement facts panel. Ask specifically about choline because the front label may imply completeness while the ingredient panel shows none.",activity:{prompt:"Which statement about prenatal supplements and choline is accurate?",options:[{text:"Many prenatal products contain little or no choline, so the label and diet must be checked",correct:true,feedback:"Correct. A prenatal is not automatically complete."},{text:"Folic acid performs every function of choline",correct:false,feedback:"They interact in metabolism but are not substitutes."},{text:"Only animal cells contain choline",correct:false,feedback:"All plant and animal cells contain choline, although amounts vary."}]}} ,
      {id:"l9-m10",title:"Audit the whole prenatal plan, not one headline nutrient",highYield:"A supplement is one tool: compare the complete label with local guidance, diet, laboratory results, medicines and changing needs across preconception, pregnancy and lactation.",teaching:["A safe audit records product name, exact serving, dose and chemical form for folic acid/folate, iron, iodine, B12, vitamin D and choline; it also checks calcium, DHA and other ingredients. Then identify duplicates from stand-alone products, fortified foods, antacids and specialty formulas. Minerals may interfere with each other or with medicines when taken together, so timing and medical review can matter.","Avoid treating the tolerable upper level as a target or converting a population recommendation into a personal prescription. Thyroid disease, anemia, malabsorption, bariatric surgery, multiple pregnancy, medications and previous neural-tube-defect risk can change the plan. Repeat the audit after nausea resolves, prescriptions change, laboratory results return and feeding method becomes known postpartum."],keyPoints:["Record form, dose, serving and frequency.","Check missing nutrients and duplicates.","UL is a safety ceiling, not a goal.","Reassess as pregnancy and lactation change."],visual:{title:"Prenatal product audit",kind:"sequence",items:[{label:"Inventory",detail:"Every prenatal, stand-alone supplement, fortified product and medicine"},{label:"Compare",detail:"Local guidance plus individual diet and risk"},{label:"Correct",detail:"Missing, duplicate, excessive or unsuitable forms"},{label:"Coordinate",detail:"Prenatal clinician, pharmacist and qualified nutrition care"},{label:"Repeat",detail:"After labs, symptoms, medication or feeding changes"}]},mnemonic:{title:"I-C-C-C-R",cue:"Inventory · Compare · Correct · Coordinate · Repeat",explanation:"A prenatal audit is a cycle, not a one-time purchase."},goodToKnow:"More pills can create both excess and false reassurance; the correct question is whether the total plan covers this person's needs safely.",practiceConnection:"Never advise stopping prescribed iron or thyroid medicine from a supplement audit alone. Flag the interaction or duplication and coordinate with the prescribing team.",activity:{prompt:"What is the best first step when a client uses a prenatal, separate iron, kelp and a greens powder?",options:[{text:"Inventory exact forms, doses and frequencies before judging the total plan",correct:true,feedback:"Correct. The products may leave gaps, duplicate nutrients or create unsafe exposure."},{text:"Assume all products are needed because they are marketed for pregnancy",correct:false,feedback:"Marketing does not establish necessity or safe total exposure."},{text:"Stop every product immediately",correct:false,feedback:"Abrupt changes can be unsafe; assess and coordinate care."}]}}
    ]}
  ],
  caseStudy:{title:"A unit error in a prenatal plan",scenario:"A vegan client planning pregnancy copied '150 mg iodine' from a course question and bought a kelp product. They also take folic acid but no B12, drink tea with meals and assume algae foods supply DHA and B12.",prompts:["Which source error creates the most immediate dosing concern?","Which nutrient plans are unreliable?","What should be confirmed with the prenatal care team?","How would you explain the evidence uncertainty around vegetarian pregnancy outcomes?"],takeaway:"Pregnancy magnifies the cost of unit errors and unreliable sources. Correct the source, verify measured B12 and iodine, assess iron and omega-3 planning, and coordinate qualified prenatal care."},
  recap:["Current adult vegetarian evidence does not automatically establish pregnancy guidance.","Preconception planning should verify folic acid, B12, iron and iodine.","The supplied 150 mg iodine statement is a likely microgram/milligram source error.","Protein and energy should be distributed through tolerable meals and snacks.","Algal DHA is the direct vegetarian long-chain omega-3 source.","Choline supports membranes, signalling and fetal development, yet many prenatals contain little or none.","Food safety and nausea strategies are individualized.","Milk calcium is relatively buffered, while B12 and iodine depend more on maternal status.","A prenatal product must be audited for form, dose, omissions, duplicates and interactions.","Postpartum needs require reassessment rather than automatic stopping or doubling of supplements."],
  flashcards:[{front:"Pregnancy evidence boundary",back:"Current adult vegetarian position guidance does not substitute for pregnancy- and lactation-specific evidence and care.",tag:"evidence"},{front:"FAB-I",back:"Folate, B12, iron and iodine—four explicit preconception checks.",tag:"preconception"},{front:"Iodine unit error",back:"150 mg equals 150,000 micrograms; prenatal guidance is ordinarily expressed in micrograms.",tag:"safety"},{front:"Pregnancy iron",back:"Needs rise; assess diet, vitamin C pairing, biomarkers and prenatal supplementation policy.",tag:"iron"},{front:"Reliable prenatal B12",back:"A measured supplement and/or confirmed fortified foods, reviewed for dose and adherence.",tag:"B12"},{front:"ALA",back:"Essential omega-3 from flax, chia, hemp, walnuts and selected oils.",tag:"omega-3"},{front:"Algal DHA",back:"The direct vegetarian DHA source considered for pregnancy and lactation under guidance.",tag:"omega-3"},{front:"Hyperemesis red flags",back:"Persistent vomiting, dehydration, inability to retain intake and significant weight loss require clinical care.",tag:"safety"},{front:"Pregnancy food safety",back:"Pasteurization, cooking, refrigeration, produce hygiene and current local high-risk-food guidance.",tag:"safety"},{front:"Milk calcium",back:"Relatively buffered; short-term maternal calcium intake has limited effect on milk calcium concentration.",tag:"lactation"},{front:"Lactation BID",back:"B12, iodine and DHA deserve explicit review; vitamin D and overall intake also matter.",tag:"lactation"},{front:"Postpartum reassessment",back:"Review recovery, feeding method, supplements, labs, food access and maternal/infant red flags.",tag:"postpartum"},{front:"Choline roles",back:"Cell membranes, acetylcholine production, methyl metabolism and lipid transport.",tag:"choline"},{front:"Plant choline sources",back:"Soybeans and soy foods, legumes, cruciferous vegetables, whole grains, nuts and seeds.",tag:"choline"},{front:"Prenatal audit",back:"Inventory, compare, correct, coordinate and repeat; check form, dose, omissions and duplicates.",tag:"supplements"}],
  practice:[{prompt:"Why is an adult vegetarian position paper insufficient for pregnancy care?",answer:"Its population and evidence scope do not establish pregnancy or lactation recommendations.",rationale:"Life stages require separate outcomes and safeguards.",tag:"evidence"},{prompt:"Name four preconception nutrient checks.",answer:"Folic acid, B12, iron and iodine; vitamin D, calcium, protein and energy also need review.",rationale:"Early development and pregnancy demands reduce the margin for error.",tag:"preconception"},{prompt:"Correct the iodine unit in the supplied question.",answer:"The statement likely intended micrograms, not milligrams; 150 mg would be 150,000 micrograms.",rationale:"A thousand-fold unit error is a safety issue.",tag:"iodine"},{prompt:"Why is the old bean-serving target not a universal prescription?",answer:"Serving systems, portions, needs, appetite and cultural foods vary; assess actual protein and energy.",rationale:"Planning aids are not physiology.",tag:"protein"},{prompt:"What is the direct vegetarian DHA source?",answer:"A measured algal DHA product.",rationale:"It bypasses limited, variable ALA conversion.",tag:"omega-3"},{prompt:"Why should tea timing be reviewed in pregnancy?",answer:"Tea polyphenols can inhibit nonheme iron absorption in the same meal.",rationale:"Iron demand is high in pregnancy.",tag:"iron"},{prompt:"Name two pregnancy nausea strategies and one red flag.",answer:"Small frequent meals and food before rising are examples; dehydration or inability to keep food down is a red flag.",rationale:"Self-care strategies do not replace hyperemesis assessment.",tag:"safety"},{prompt:"Which milk nutrient is relatively buffered?",answer:"Calcium.",rationale:"Milk calcium does not simply rise with very high maternal intake.",tag:"lactation"},{prompt:"Why is maternal B12 status urgent in lactation?",answer:"Low milk B12 can cause severe infant neurologic injury.",rationale:"Infants have small stores and rapid growth.",tag:"B12"},{prompt:"What should happen to the prenatal plan after birth?",answer:"Reassess it against recovery, blood loss, feeding method, diet, labs and pediatric guidance.",rationale:"Needs continue but may change.",tag:"postpartum"},{prompt:"Why must choline be checked separately from folic acid?",answer:"Choline has distinct structural, neurotransmitter and metabolic roles, and many prenatals contain little or none.",rationale:"Related one-carbon pathways do not make these nutrients interchangeable.",tag:"choline"},{prompt:"Name four fields in a prenatal supplement audit.",answer:"Examples: chemical form, dose per serving, number of servings, frequency, missing nutrients, duplicates and medicine interactions.",rationale:"The product name alone does not establish a safe complete plan.",tag:"supplements"}],
  sources:[{title:"Health Canada · Nutrition during pregnancy and breastfeeding",url:"https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/applying/advice-nutrition-different-life-stages/considerations-pregnancy-support-breastfeeding.html"},{title:"NIH ODS · Dietary supplements and pregnancy",url:"https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"},{title:"NIH ODS · Choline",url:"https://ods.od.nih.gov/factsheets/Choline-HealthProfessional/"},{title:"NIH ODS · Iodine",url:"https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/"}]
};
